const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Apply SAVE20OFF: \$20 flat discount
const result = db.prepare(\"
  UPDATE carts 
  SET discount_amount = 20, 
      total = subtotal - 20 + shipping_cost + gift_wrap_fee - loyalty_discount, 
      applied_promo_codes_json = '[\"SAVE20OFF\"]' 
  WHERE cart_id = 'CART-user_03dd1ad7'
\").run();
console.log('Rows updated:', result.changes);

// Verify the updated cart
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_03dd1ad7'\").get();
console.log(JSON.stringify(cart, null, 2));
"

